-- Adds 40 sourced, non-Daily Animals questions to the shared question bank.
-- Percentage bounds use the project-wide 0-100 slider rule.

insert into public.questions (
  id, category, measure, subtype, prompt, answer, min, max, scale, unit,
  reference_year, source_title, source_url, explanation, is_daily
) values
  ('animals-mass-galapagos-tortoise-male', 'animals', 'size', 'mass', 'How much can a large male Galápagos giant tortoise weigh?', 260, 20, 1000, 'log', 'kilogram', null, 'San Diego Zoo Wildlife Alliance — Galápagos Tortoise', 'https://animals.sandiegozoo.org/animals/galapagos-tortoise', 'Males reach about 260 kilograms (573 pounds), roughly three times the weight of the females they share the islands with.', false),
  ('animals-mass-gorilla-adult-male', 'animals', 'size', 'mass', 'What does a large adult male gorilla weigh?', 181, 40, 500, 'log', 'kilogram', null, 'San Diego Zoo Wildlife Alliance — Gorilla', 'https://animals.sandiegozoo.org/animals/gorilla', 'A silverback tops out around 181 kilograms (400 pounds) — heavy, but only about double a grown man, despite the fearsome reputation.', false),
  ('animals-mass-northern-elephant-seal-male', 'animals', 'size', 'mass', 'How much can a fully grown male northern elephant seal weigh?', 2000, 200, 6000, 'log', 'kilogram', null, 'NOAA Fisheries — Northern Elephant Seal', 'https://www.fisheries.noaa.gov/species/northern-elephant-seal', 'Bulls reach nearly 4,400 pounds, about 2,000 kilograms, which is roughly three times the weight of the females they tower over on the beach.', false),
  ('animals-mass-antarctic-krill-biomass', 'animals', 'size', 'mass', 'What is the estimated total weight of all the Antarctic krill in the Southern Ocean?', 400000000, 1000000, 5000000000, 'log', 'tonne', null, 'Australian Antarctic Program — Krill', 'https://www.antarctica.gov.au/about-antarctica/animals/krill/', 'Around 400 million tonnes of these shrimp-like creatures drift in the Southern Ocean, making them one of the most abundant animals on Earth by sheer mass.', false),
  ('animals-length-narwhal-tusk', 'animals', 'size', 'length', 'How long can a narwhal''s tusk grow?', 3, 0.5, 8, 'linear', 'metre', null, 'NOAA Fisheries — Narwhal', 'https://www.fisheries.noaa.gov/species/narwhal', 'The spiralled tusk — actually an overgrown left canine tooth — can reach 3 metres (9.8 feet) and weigh over 20 pounds.', false),
  ('animals-length-giraffe-male-height', 'animals', 'size', 'length', 'How tall can an adult male giraffe stand?', 5.5, 2, 10, 'linear', 'metre', null, 'San Diego Zoo Wildlife Alliance — Giraffe', 'https://animals.sandiegozoo.org/animals/giraffe', 'Males reach 5.5 metres (18 feet), tall enough to peer into a second-storey window, with a neck alone weighing about 272 kilograms.', false),
  ('animals-length-blue-whale-maximum', 'animals', 'size', 'length', 'How long can the largest blue whales grow?', 33.5, 10, 60, 'linear', 'metre', null, 'NOAA Fisheries — Blue Whale', 'https://www.fisheries.noaa.gov/species/blue-whale', 'Antarctic blue whales reach about 110 feet, or 33.5 metres — longer than a basketball court and the largest animal that has ever lived.', false),
  ('animals-length-giant-manta-ray-disc-width', 'animals', 'size', 'length', 'How wide can a giant manta ray measure from wingtip to wingtip?', 7.9, 1, 15, 'linear', 'metre', null, 'NOAA Fisheries — Giant Manta Ray', 'https://www.fisheries.noaa.gov/species/giant-manta-ray', 'The world''s largest ray spans up to 26 feet — about 7.9 metres — while weighing as much as 5,300 pounds.', false),
  ('animals-length-goliath-birdeater-leg-span', 'animals', 'size', 'length', 'How wide is the leg span of a Goliath bird-eating spider, the largest tarantula?', 0.28, 0.05, 0.6, 'linear', 'metre', null, 'San Diego Zoo Wildlife Alliance — Tarantula', 'https://animals.sandiegozoo.org/animals/tarantula', 'Male Goliath bird-eaters span 28 centimetres across the legs — about the size of a dinner plate.', false),
  ('animals-length-greater-flamingo-height', 'animals', 'size', 'length', 'How tall can a greater flamingo stand?', 1.45, 0.5, 2.5, 'linear', 'metre', null, 'San Diego Zoo Wildlife Alliance — Flamingo', 'https://animals.sandiegozoo.org/animals/flamingo', 'The greater flamingo reaches 145 centimetres, roughly eye-to-eye with a ten-year-old child, yet weighs only about 4 kilograms.', false),
  ('animals-length-black-rhino-front-horn', 'animals', 'size', 'length', 'How long can a black rhino''s front horn grow?', 1.3, 0.2, 2.5, 'linear', 'metre', null, 'San Diego Zoo Wildlife Alliance — Rhinoceros', 'https://animals.sandiegozoo.org/animals/rhinoceros', 'Black rhinos grow the longest horns of any rhino, with the front horn reaching 1.3 metres (4 feet) of compacted keratin — the same material as your fingernails.', false),
  ('animals-length-lion-roar-audible-distance', 'animals', 'size', 'length', 'How far away can a lion''s roar be heard?', 4.8, 0.5, 20, 'log', 'kilometre', null, 'San Diego Zoo Wildlife Alliance — Lion', 'https://animals.sandiegozoo.org/animals/lion', 'A lion''s roar carries about 4.8 kilometres (3 miles) across the savanna, which is how prides advertise their territory without moving a paw.', false),
  ('animals-area-yellowstone-wolf-pack-home-range', 'animals', 'size', 'area', 'How large is the average wolf pack home range on Yellowstone''s northern range?', 274, 10, 3000, 'log', 'square-kilometre', null, 'U.S. National Park Service — Yellowstone Wolf Ecology', 'https://www.nps.gov/yell/learn/nature/wolf.htm', 'Northern-range packs patrol about 274 square kilometres each, while packs in the park''s interior roam more than twice that area.', false),
  ('animals-count-porcupine-quills', 'animals', 'quantity', 'count', 'Roughly how many quills does a North American porcupine carry?', 30000, 500, 200000, 'log', 'count', null, 'San Diego Zoo Wildlife Alliance — Porcupine', 'https://animals.sandiegozoo.org/animals/porcupine', 'A single porcupine bristles with over 30,000 quills, packed as densely as 150 to the square inch — and contrary to myth, it cannot shoot them.', false),
  ('animals-count-sea-otter-hairs-per-square-inch', 'animals', 'quantity', 'count', 'Roughly how many hairs grow in a single square inch of a sea otter''s fur?', 1000000, 10000, 5000000, 'log', 'count', null, 'Monterey Bay Aquarium — Sea Otter', 'https://www.montereybayaquarium.org/animals/animals-a-to-z/sea-otter', 'Sea otters pack more than a million hairs into each square inch — the densest fur of any animal, and the only insulation they have, since they carry no blubber.', false),
  ('animals-count-honeybee-queen-eggs-per-day', 'animals', 'quantity', 'count', 'How many eggs can a honeybee queen lay in a single day?', 2000, 50, 20000, 'log', 'count', null, 'San Diego Zoo Wildlife Alliance — Bee', 'https://animals.sandiegozoo.org/animals/bee', 'A queen lays up to 2,000 eggs a day — more than her own body weight — and keeps it up for two to five years.', false),
  ('animals-count-chameleon-species', 'animals', 'quantity', 'count', 'According to San Diego Zoo Wildlife Alliance''s 2026 listing, how many chameleon species are there?', 158, 20, 1000, 'log', 'count', '2026', 'San Diego Zoo Wildlife Alliance — Chameleon', 'https://animals.sandiegozoo.org/animals/chameleon', 'There are 158 chameleon species, and nearly two-thirds of them live nowhere but Madagascar.', false),
  ('animals-count-yellowstone-bison-population', 'animals', 'quantity', 'count', 'According to the 2025 estimate, how many bison lived in Yellowstone National Park?', 5300, 300, 40000, 'log', 'count', '2025', 'U.S. National Park Service — Yellowstone Bison', 'https://www.nps.gov/yell/learn/nature/bison.htm', 'About 5,300 bison roamed Yellowstone in 2025, descended from the couple of dozen wild animals that survived there in the early 1900s.', false),
  ('animals-count-carlsbad-cavern-bat-colony', 'animals', 'quantity', 'count', 'Roughly how many Brazilian free-tailed bats made up Carlsbad Cavern''s resident summer colony in 2005?', 400000, 10000, 5000000, 'log', 'count', '2005', 'U.S. National Park Service — Bats of Carlsbad Caverns', 'https://www.nps.gov/cave/learn/nature/bats.htm', 'About 400,000 bats formed the summer colony in 2005, and migration pushed the cavern''s total as high as 793,000 that same year.', false),
  ('animals-count-giant-anteater-tongue-flicks', 'animals', 'quantity', 'count', 'How many times per minute can a giant anteater flick its tongue in and out?', 150, 10, 600, 'log', 'count', null, 'Smithsonian''s National Zoo — Giant Anteater', 'https://nationalzoo.si.edu/animals/giant-anteater', 'The tongue darts up to 150 times a minute — two and a half flicks every second — though the anteater takes only about 140 insects from each mound before moving on.', false),
  ('animals-count-alligator-lifetime-teeth', 'animals', 'quantity', 'count', 'How many teeth can an American alligator go through in its lifetime?', 3000, 80, 20000, 'log', 'count', null, 'Smithsonian''s National Zoo — American Alligator', 'https://nationalzoo.si.edu/animals/american-alligator', 'An alligator holds 74 to 80 teeth at a time but replaces them endlessly, working through some 3,000 over a life of about 50 years.', false),
  ('animals-count-green-turtle-eggs-per-nest', 'animals', 'quantity', 'count', 'About how many eggs does a green sea turtle lay in one nest?', 110, 10, 600, 'log', 'count', null, 'NOAA Fisheries — Green Turtle', 'https://www.fisheries.noaa.gov/species/green-turtle', 'Each nest holds about 110 eggs, buried in warm sand for roughly two months before the hatchlings dig out and race for the sea.', false),
  ('animals-count-bald-eagle-breeding-pairs-1963', 'animals', 'quantity', 'count', 'At their lowest point in 1963, how many breeding pairs of bald eagles were left in the lower 48 states?', 417, 50, 50000, 'log', 'count', '1963', 'Smithsonian''s National Zoo — Bald Eagle', 'https://nationalzoo.si.edu/animals/bald-eagle', 'Just 417 breeding pairs remained in 1963; after DDT was banned the population rebounded to more than 71,400 pairs by 2020.', false),
  ('animals-count-meerkat-burrow-entrances', 'animals', 'quantity', 'count', 'On average, how many entrance and exit holes does a meerkat burrow have?', 15, 1, 60, 'linear', 'count', null, 'San Diego Zoo Wildlife Alliance — Meerkat', 'https://animals.sandiegozoo.org/animals/meerkat', 'A typical burrow has about 15 doorways leading into tunnels that run 2 metres deep, so a meerkat is never far from an escape route.', false),
  ('animals-percentage-camel-survivable-weight-loss', 'animals', 'quantity', 'percentage', 'What percentage of its body weight can a camel lose and still survive?', 40, 0, 100, 'linear', 'percent', null, 'San Diego Zoo Wildlife Alliance — Camel', 'https://animals.sandiegozoo.org/animals/camel', 'A camel can shed 40 percent of its body weight and live, then rehydrate by drinking up to 145 litres in a single session.', false),
  ('animals-percentage-kiwi-chick-survival', 'animals', 'quantity', 'percentage', 'Without predator control, what percentage of wild kiwi chicks survive to six months old?', 10, 0, 100, 'linear', 'percent', null, 'New Zealand Department of Conservation — Kiwi Facts', 'https://www.doc.govt.nz/nature/native-animals/birds/birds-a-z/kiwi/facts/', 'Only 10 percent of kiwi chicks reach six months where predators go unmanaged, which is why around 70,000 birds are left and unmanaged populations fall 2 percent a year.', false),
  ('animals-percentage-dangerous-snake-species', 'animals', 'quantity', 'percentage', 'What percentage of the world''s snake species are considered dangerous to humans?', 15, 0, 100, 'linear', 'percent', null, 'San Diego Zoo Wildlife Alliance — Snake', 'https://animals.sandiegozoo.org/animals/snake', 'Only about 15 percent of the roughly 2,978 known snake species pose any danger to people — more people are struck by lightning than bitten by a venomous snake.', false),
  ('animals-percentage-alligator-hatchling-losses', 'animals', 'quantity', 'percentage', 'What percentage of young American alligators are lost to predators?', 80, 0, 100, 'linear', 'percent', null, 'Smithsonian''s National Zoo — American Alligator', 'https://nationalzoo.si.edu/animals/american-alligator', 'Some 80 percent of hatchlings are eaten by birds, raccoons and even other alligators, which is why a female may lay up to 90 eggs at once.', false),
  ('animals-temperature-two-toed-sloth-body', 'animals', 'physics', 'temperature', 'How low can a two-toed sloth''s body temperature drop?', 30, 18, 42, 'linear', 'celsius', null, 'Smithsonian''s National Zoo — Two-Toed Sloth', 'https://nationalzoo.si.edu/animals/two-toed-sloth', 'Sloths run a famously cool and variable 30 to 34 degrees Celsius, part of an energy-saving lifestyle so slow that a meal takes a month to digest.', false),
  ('animals-temperature-emperor-penguin-huddle', 'animals', 'physics', 'temperature', 'How warm can it get inside an emperor penguin huddle?', 24, -30, 40, 'linear', 'celsius', null, 'Australian Antarctic Program — Emperor Penguins', 'https://www.antarctica.gov.au/about-antarctica/animals/penguins/emperor-penguins/', 'Packed ten birds to the square metre, the middle of a huddle reaches a balmy +24 °C while the Antarctic winter rages outside.', false),
  ('animals-duration-naked-mole-rat-lifespan', 'animals', 'physics', 'duration', 'How long can a naked mole-rat live in human care?', 30, 2, 80, 'linear', 'duration-year', null, 'Smithsonian''s National Zoo — Naked Mole-Rat', 'https://nationalzoo.si.edu/animals/naked-mole-rat', 'Naked mole-rats reach around 30 years, extraordinary for a rodent the size of a sausage — most mice are gone within three.', false),
  ('animals-duration-killer-whale-female-lifespan', 'animals', 'physics', 'duration', 'How old can a female killer whale live to be in the wild?', 90, 20, 160, 'linear', 'duration-year', null, 'NOAA Fisheries — Killer Whale', 'https://www.fisheries.noaa.gov/species/killer-whale', 'Females can reach at least 90 years — typically 50 — while males average about 30, one of the widest lifespan gaps between sexes in the animal kingdom.', false),
  ('animals-duration-humpback-alaska-hawaii-crossing', 'animals', 'physics', 'duration', 'In as few as how many days can a humpback whale swim from Alaska to Hawaii?', 28, 3, 150, 'linear', 'day', null, 'NOAA Fisheries — Humpback Whale', 'https://www.fisheries.noaa.gov/species/humpback-whale', 'Some humpbacks cover the 3,000-mile crossing in just 28 days, and they do it largely without stopping to feed.', false),
  ('animals-duration-beaver-underwater', 'animals', 'physics', 'duration', 'How long can a beaver stay underwater?', 15, 1, 45, 'linear', 'minute', null, 'Smithsonian''s National Zoo — Beaver', 'https://nationalzoo.si.edu/animals/beaver', 'Oversized lungs let a beaver stay submerged for up to 15 minutes, long enough to swim more than half a mile without surfacing.', false),
  ('animals-duration-cheetah-acceleration', 'animals', 'physics', 'duration', 'How many seconds does a cheetah need to accelerate from a standstill to 72 kilometres per hour?', 2.5, 0.5, 12, 'linear', 'second', null, 'Smithsonian''s National Zoo — Cheetah', 'https://nationalzoo.si.edu/animals/cheetah', 'A cheetah hits 45 miles per hour in 2.5 seconds, out-accelerating most sports cars, and covers 7 metres in a single stride.', false),
  ('animals-duration-platypus-water-foraging', 'animals', 'physics', 'duration', 'At most, how many hours can a platypus spend in the water feeding at one time?', 10, 1, 24, 'linear', 'hour', null, 'NSW Environment and Heritage - Platypus', 'https://www.environment.nsw.gov.au/topics/animals-and-plants/native-animals/native-animal-facts/land-mammals/platypus', 'A platypus can spend up to 10 hours in the water feeding, hunting with its eyes and ears closed and using its sensitive bill to detect prey.', false),
  ('animals-duration-koala-daily-sleep', 'animals', 'physics', 'duration', 'At most, how many hours a day does a koala sleep?', 22, 6, 24, 'linear', 'hour', null, 'San Diego Zoo Wildlife Alliance — Koala', 'https://animals.sandiegozoo.org/animals/koala', 'Koalas rest 18 to 22 hours a day, because a diet of tough, low-energy eucalyptus leaves simply cannot fuel anything more ambitious.', false),
  ('animals-speed-hippo-charge', 'animals', 'physics', 'speed', 'How fast can an agitated hippo charge on land?', 30, 5, 80, 'linear', 'kph', null, 'San Diego Zoo Wildlife Alliance — Hippo', 'https://animals.sandiegozoo.org/animals/hippo', 'A hippo can charge at 30 kilometres per hour — faster than most people can sprint — despite weighing up to 4,500 kilograms.', false),
  ('animals-money-us-lobster-landings-value', 'animals', 'quantity', 'money', 'How much were US commercial American lobster landings worth in 2024?', 720000000, 10000000, 5000000000, 'log', 'usd', '2024', 'NOAA Fisheries — American Lobster', 'https://www.fisheries.noaa.gov/species/american-lobster', 'Fishers landed 113 million pounds of lobster in 2024, worth about $720 million — one of the most valuable single-species fisheries in the United States.', false),
  ('animals-money-us-alaska-pollock-landings-value', 'animals', 'quantity', 'money', 'How much were US commercial Alaska pollock landings worth in 2024?', 432000000, 20000000, 3000000000, 'log', 'usd', '2024', 'NOAA Fisheries — Alaska Pollock', 'https://www.fisheries.noaa.gov/species/alaska-pollock', 'Over 3 billion pounds of Alaska pollock came ashore in 2024 for about $432 million — a colossal catch that ends up in fish sticks and imitation crab.', false);
